import { test, expect } from '@playwright/test';

test.describe('User Profile Language Preference', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/profile');
    await page.getByRole('button', { name: 'Edit Profile' }).click();
  });

  test('should display current language preference', async ({ page }) => {
    const currentLanguage = await page.getByLabel('Language Preference').inputValue();
    expect(currentLanguage).toBe('English'); // Assuming English is the default
  });

  test('should allow user to change language preference', async ({ page }) => {
    await page.getByLabel('Language Preference').selectOption('Spanish');
    await page.getByRole('button', { name: 'Save Changes' }).click();

    const successMessage = await page.getByText('Profile updated successfully').isVisible();
    expect(successMessage).toBe(true);

    const updatedLanguage = await page.getByLabel('Language Preference').inputValue();
    expect(updatedLanguage).toBe('Spanish');
  });
});
